// Fix the token-bucket accounting so bursts can't slip through after a quiet period.
// Contract: rateLimit(timestamps, capacity, refillRate) -> boolean[]  (one decision per request)
function rateLimit(timestamps, capacity, refillRate) {
  if (!timestamps.length) return [];
  let tokens = capacity;
  let last = timestamps[0];
  const decisions = [];
  for (const t of timestamps) {
    const elapsedSeconds = (t - last) / 1000;
    // Current prod behavior: refill by elapsed time, then check the bucket.
    tokens = tokens + elapsedSeconds * refillRate;
    last = t;
    if (tokens >= 1) {
      tokens -= 1;
      decisions.push(true);
    } else {
      decisions.push(false);
    }
  }
  return decisions;
}

module.exports = { rateLimit };

